    val all: List<KnowledgeArticle> by lazy { part0() + part1() + part2() + part3() }

    private fun part0(): List<KnowledgeArticle> = listOf(
        KnowledgeArticle("a-vitamin", "vitaminer", "A-vitamin", "Vigtigt for synet, huden og immunforsvaret.", listOf("A-vitamin (retinol) indgår i det lysfølsomme stof i øjets nethinde og er nødvendigt for at se i mørke. Det holder også hud og slimhinder sunde og støtter immunforsvaret.", "Du får det færdige A-vitamin fra lever, æg, mælkeprodukter og fisk. Planter indeholder betakaroten, som kroppen selv omdanner til A-vitamin efter behov.", "A-vitamin er fedtopløseligt og lagres i leveren, så for meget kan ophobes. Gravide bør undgå lever og leverpostej i store mængder."), "Gulerødder gør ikke, at du ser i mørke — men mangel på A-vitamin kan give natteblindhed.", OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("b1-vitamin", "vitaminer", "B1-vitamin (thiamin)", "Hjælper kroppen med at få energi ud af kulhydrat.", listOf("Thiamin er et hjælpestof for de enzymer, der omdanner kulhydrat til energi i cellerne. Hjernen og nerverne er særligt afhængige af det.", "Gode kilder er fuldkorn, svinekød, bælgfrugter og kerner. Meget af B1-vitaminet sidder i kornets yderste lag og forsvinder, når kornet raffineres til hvidt mel."), null, OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("b2-vitamin", "vitaminer", "B2-vitamin (riboflavin)", "Indgår i cellernes energiomsætning.", listOf("Riboflavin er byggesten i to vigtige hjælpeenzymer (FAD og FMN), som cellerne bruger til at udvinde energi fra fedt, kulhydrat og protein.", "Mælkeprodukter er den største kilde i danskernes kost, men det findes også i kød, æg og fuldkorn."), "Riboflavin er gult og lyser under UV-lys. Overskud udskilles med urinen, som kan blive knaldgul.", OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("b6-vitamin", "vitaminer", "B6-vitamin", "Vigtigt for proteinomsætning og nervesystemet.", listOf("B6-vitamin hjælper over 100 enzymer, især dem der omsætter aminosyrer. Det bruges også til at danne signalstoffer i hjernen som serotonin.", "Findes i fisk, kød, kartofler, bananer og fuldkorn. Meget høje doser fra kosttilskud over længere tid kan give nerveskader."), null, OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("b12-vitamin", "vitaminer", "B12-vitamin", "Nødvendigt for blod og nerver — findes næsten kun i animalske fødevarer.", listOf("B12 er nødvendigt for at danne røde blodlegemer og for at holde nerverne sunde. Mangel kan give blodmangel, træthed og på sigt nerveskader.", "Det dannes af bakterier og findes naturligt næsten kun i kød, fisk, æg og mælk. Veganere bør derfor tage tilskud eller spise berigede produkter."), "Leveren kan lagre B12 i flere år, så mangel opstår ofte først længe efter kostomlægning.", OnbSourceLink("Fødevarestyrelsen: Kosttilskudsanbefalinger", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/kosttilskud/kosttilskudsanbefalinger"), emptyList()),
        KnowledgeArticle("folat", "vitaminer", "Folat (folsyre)", "Vigtigt for celledeling — særligt før og under graviditet.", listOf("Folat bruges, når cellerne deler sig og danner nyt arvemateriale. Derfor er behovet stort i perioder med hurtig vækst, fx tidligt i en graviditet.", "Kvinder, der planlægger graviditet, anbefales tilskud med folsyre for at mindske risikoen for rygmarvsbrok hos fosteret.", "Navnet kommer af latin folium, blad: grønne bladgrøntsager, bælgfrugter og fuldkorn er gode kilder."), null, OnbSourceLink("Fødevarestyrelsen: Kosttilskudsanbefalinger", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/kosttilskud/kosttilskudsanbefalinger"), emptyList()),
        KnowledgeArticle("c-vitamin", "vitaminer", "C-vitamin", "Antioxidant, der også hjælper kroppen med at optage jern.", listOf("C-vitamin (ascorbinsyre) bruges til at danne kollagen, som holder hud, sener og blodkar stærke. Det er også en antioxidant og øger optagelsen af jern fra planter.", "Frugt og grønt er de vigtigste kilder — fx peberfrugt, kål, citrusfrugter og bær. C-vitamin nedbrydes af varme, så rå grøntsager giver mest."), "Mennesker er et af de få pattedyr, der ikke selv kan danne C-vitamin. Søfolk fik skørbug, indtil man opdagede, at citrusfrugter forebyggede det.", OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("d-vitamin", "vitaminer", "D-vitamin", "Hjælper kroppen med at optage kalk til knoglerne.", listOf("D-vitamin styrer optagelsen af calcium fra tarmen og er dermed afgørende for stærke knogler og muskler.", "Huden danner D-vitamin i sollys, men i Danmark er solen for svag fra oktober til april. Maden (fisk, æg, berigede produkter) dækker sjældent behovet alene.", "Derfor anbefales tilskud til mange grupper, fx små børn, ældre, gravide og personer med mørk hud eller som ikke kommer ud i solen."), "D-vitamin er teknisk set et hormon, som kroppen selv kan danne — ikke et klassisk vitamin.", OnbSourceLink("Fødevarestyrelsen: Kosttilskudsanbefalinger", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/kosttilskud/kosttilskudsanbefalinger"), emptyList()),
    )

    private fun part1(): List<KnowledgeArticle> = listOf(
        KnowledgeArticle("e-vitamin", "vitaminer", "E-vitamin", "Beskytter cellernes fedt mod iltning.", listOf("E-vitamin (tokoferol) er en fedtopløselig antioxidant, der beskytter cellemembranerne mod skader fra frie radikaler.", "Planteolier, nødder, kerner og avocado er gode kilder. Industrien tilsætter det også olier for at forhindre harskning."), null, OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("k-vitamin", "vitaminer", "K-vitamin", "Nødvendigt for at blodet kan størkne.", listOf("K-vitamin aktiverer de proteiner, der får blodet til at størkne, og spiller også en rolle for knoglerne.", "Grønne bladgrøntsager som grønkål og spinat er rige kilder, og tarmbakterierne danner selv en del. Nyfødte får en K-vitaminindsprøjtning, fordi de endnu ikke har tarmbakterier."), "K'et kommer fra det tyske ord 'Koagulation'.", OnbSourceLink("Fødevarestyrelsen: Vitaminer og mineraler", "https://foedevarestyrelsen.dk/kost-og-foedevarer/saerlige-foedevarekategorier/kosttilskud/vitaminer-og-mineraler-i-kosttilskud"), emptyList()),
        KnowledgeArticle("fuldkorn", "sundhedstips", "Fuldkorn — hvad gør det i kroppen?", "Hele kornet med kim og klid: fibre, vitaminer og et mere stabilt blodsukker.", listOf("Et korn består af tre dele: klid (skallen), kimen (spiren) og endospermen (stivelseslageret). Fuldkorn betyder, at alle tre dele er med. Hvidt mel er kun endospermen.", "Kliddet er fyldt med kostfibre. De fordøjes ikke i tyndtarmen, men binder vand, giver mere volumen i tarmen og får maden til at passere lettere. Det giver også længere mæthed.", "Kimen indeholder B-vitaminer, E-vitamin, sunde fedtstoffer og mineraler som jern, zink og magnesium. Det er netop de dele, der forsvinder, når kornet raffineres.", "Fordi stivelsen er pakket ind i fibre, nedbrydes den langsommere. Sukkeret kommer derfor gradvist ud i blodet i stedet for i et hurtigt ryk.", "I tyktarmen fermenterer tarmbakterierne en del af fibrene og danner kortkædede fedtsyrer, som nærer tarmslimhinden. Et højt indtag af fuldkorn er forbundet med lavere risiko for type 2-diabetes, hjerte-kar-sygdom og tarmkræft.", "Anbefalingen er mindst 75 g fuldkorn om dagen for voksne (pr. 10 MJ). Kig efter fuldkornslogoet, når du handler."), "Rugbrød er en af verdens bedste fuldkornskilder — danskerne får mere fuldkorn end de fleste andre europæere, netop på grund af rugbrødet.", OnbSourceLink("Fødevarestyrelsen: Spis mad med fuldkorn", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/de-officielle-kostraad/kostraad-til-dig/om-de-officielle-kostraad/spis-mad-med-fuldkorn"), emptyList()),
        KnowledgeArticle("kostfibre", "sundhedstips", "Kostfibre — maden til dine tarmbakterier", "Fibre mætter, holder maven i gang og fodrer de gode bakterier.", listOf("Kostfibre er de dele af planter, som kroppens egne enzymer ikke kan nedbryde. Uopløselige fibre (fx i klid) giver volumen og gør afføringen blødere. Opløselige fibre (fx i havre og bælgfrugter) danner en gel, der kan sænke kolesterol.", "Voksne anbefales 25-35 g kostfibre om dagen. Frugt, grønt, bælgfrugter og fuldkorn er de bedste kilder.", "Øg mængden gradvist og drik vand til, så maven kan vænne sig til det."), "Du har flere bakterieceller i tarmen, end du har menneskeceller i kroppen — og mange af dem lever af fibre.", OnbSourceLink("Fødevarestyrelsen: Spis mad med fuldkorn", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/de-officielle-kostraad/kostraad-til-dig/om-de-officielle-kostraad/spis-mad-med-fuldkorn"), emptyList()),
        KnowledgeArticle("tilsat-sukker", "sundhedstips", "Tilsat sukker — hvor meget er for meget?", "Højst 10 % af energien bør komme fra tilsat sukker.", listOf("Tilsat sukker giver energi uden vitaminer, mineraler eller fibre. Derfor anbefales det, at tilsat og frit sukker højst udgør 10 % af dagens energi — gerne mindre.", "Frit sukker omfatter også honning, sirup og frugtjuice. Sukkeret i hel frugt og mælk tæller ikke med, fordi det følger med fibre og næringsstoffer.", "Sukker gemmer sig under mange navne i ingredienslisten, fx dextrose, glukosesirup, maltose og maltodextrin."), "En almindelig sodavand på 50 cl indeholder omkring 50 g sukker — mere end det meste af en dags anbefalede maksimum for et barn.", OnbSourceLink("Fødevarestyrelsen: Spis mindre af det søde, salte og fede", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/de-officielle-kostraad/kostraad-til-dig/om-de-officielle-kostraad/spis-mindre-af-det-soede-salte-og-fede"), emptyList()),
        KnowledgeArticle("vand", "sundhedstips", "Vand — kroppens vigtigste næringsstof", "Kroppen består af ca. 60 % vand og taber flere liter hver dag.", listOf("Vand transporterer næringsstoffer, regulerer kropstemperaturen og fjerner affaldsstoffer via nyrerne.", "Du taber vand gennem urin, sved og udåndingsluft. Tørst er et tidligt signal, og let væskemangel kan give hovedpine og nedsat koncentration.", "Vand fra hanen er det bedste valg som tørstslukker — det giver ingen kalorier."), "Hjernen består af omkring 75 % vand.", OnbSourceLink("Fødevarestyrelsen: De officielle kostråd", "https://foedevarestyrelsen.dk/kost-og-foedevarer/alt-om-mad/de-officielle-kostraad/kostraad-til-dig"), emptyList()),
        KnowledgeArticle("sadan-forbraender-kroppen-kalorier", "kalorieforbraending", "Sådan forbrænder kroppen kalorier", "Hvilende forbrænding, fordøjelse og bevægelse — tre poster på dagens regnskab.", listOf("Det daglige energiforbrug består af tre dele: grundforbrændingen (energien kroppen bruger i hvile til hjerte, hjerne, åndedræt og varme), den kostbetingede varmeudvikling (energien det koster at fordøje og optage maden) og energien til fysisk aktivitet.", "For de fleste er grundforbrændingen den største post. Det er derfor, to personer med samme højde og vægt kan have forskelligt behov: alder, køn, muskelmasse og genetik spiller ind. Appens kaloriemål er et estimat, ikke en facitliste.", "Aktivitet fylder mest hos dem, der bevæger sig meget. Men også almindelig hverdagsbevægelse tæller (se artiklen om NEAT)."), null, OnbSourceLink("Westerterp KR (2004): Diet induced thermogenesis. Nutrition & Metabolism (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/15507147/"), emptyList()),
        KnowledgeArticle("forbraending-i-loebet-af-dagen", "kalorieforbraending", "Hvordan bør forbrændingen fordele sig over dagen?", "Forskning peger på, at kroppen bruger mere energi på at fordøje morgenmad end aftensmad.", listOf("I et lille kontrolleret studie fra 2020 fik de samme personer det samme måltid om morgenen og om aftenen. Den energi, kroppen brugte på at fordøje måltidet, var cirka dobbelt så høj efter morgenmad som efter aftensmad. Studiet er lille, og forskere diskuterede det efterfølgende, så tallet skal ikke tages som en garanti for vægttab.", "Det passer med en praktisk tommelfingerregel mange kostråd bygger på: Læg en god del af dagens energi tidligt, og lad aftensmaden være moderat. Så følger din energiindtagelse dagens aktivitet, i stedet for at komme lige før du skal sove.", "Aktivitet fordeler sig bedst jævnt: WHO anbefaler at bryde lange perioder med stillesiddende tid. Små gåture, trapper og stående pauser i løbet af dagen giver mere forbrænding end én enkelt træning efter en hel dag i en stol — og de supplerer træningen, de erstatter den ikke.", "Tip: Spis en morgenmad med protein og fibre, flyt et stort måltid fra sen aften til frokost, og gå en kort tur efter måltider."), null, OnbSourceLink("Richter J m.fl. (2020): Twice as high diet-induced thermogenesis after breakfast vs dinner. J Clin Endocrinol Metab (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/32073608/"), listOf(OnbSourceLink("WHO: Guidelines on physical activity and sedentary behaviour (2020)", "https://www.who.int/publications/i/item/9789240015128"))),
    )

    private fun part2(): List<KnowledgeArticle> = listOf(
        KnowledgeArticle("neat-hverdagsbevaegelse", "kalorieforbraending", "NEAT — forbrænding uden at træne", "Småbevægelser, stå-op-pauser og gåture kan tælle mere end du tror.", listOf("NEAT (non-exercise activity thermogenesis) er den energi, du bruger på alt andet end planlagt motion: at gå, stå, rejse dig, rumstere i køkkenet og fumle med fingrene.", "I et klassisk studie fik 16 raske frivillige 1.000 kcal for meget om dagen i otte uger. Cirka to tredjedele af stigningen i deres energiforbrug kom fra NEAT, og forskelle i NEAT forklarede de store forskelle i, hvor meget fedt den enkelte lagde på.", "Tricks: tag trappen, stå op ved telefonopkald, gå, mens du taler i telefon, parkér lidt længere væk og sæt en påmindelse hver time om at rejse dig."), "Forskellen i fedtlagring mellem deltagerne var op til ti gange — selvom de alle spiste det samme overskud.", OnbSourceLink("Levine JA m.fl. (1999): Role of nonexercise activity thermogenesis in resistance to fat gain in humans. Science (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/9880251/"), emptyList()),
        KnowledgeArticle("protein-og-kostbetinget-forbraending", "kalorieforbraending", "Protein og fordøjelsens energiforbrug", "Kroppen bruger energi på at fordøje maden — mest på protein.", listOf("Fordøjelsen koster energi. Den kostbetingede termogenese udgør typisk en mindre del af dagens forbrug, og størrelsen afhænger af måltidets sammensætning og størrelse.", "Protein kræver mere energi at fordøje og omsætte end kulhydrat og fedt, og protein mætter desuden godt. Derfor kan et måltid med protein hjælpe, hvis du vil holde sulten i ro.", "Det gør ikke maden 'kalorie-fri': Effekten er beskeden, og mange får nok protein i en varieret kost. Et ekstremt højt proteinindtag er hverken nødvendigt eller anbefalet for de fleste."), null, OnbSourceLink("Westerterp KR (2004): Diet induced thermogenesis. Nutrition & Metabolism (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/15507147/"), listOf(OnbSourceLink("Nordisk Ministerråd: Nordic Nutrition Recommendations 2023", "https://norden.org/en/publication/nordic-nutrition-recommendations-2023"))),
        KnowledgeArticle("motion-kompenseres-af-kroppen", "kalorieforbraending", "Hvorfor motion alene sjældent er nok", "Forskning peger på, at kroppen tilpasser sig højt aktivitetsniveau.", listOf("Et studie af voksne i flere lande undersøgte sammenhængen mellem aktivitet og samlet energiforbrug. Resultatet: Ved lav aktivitet stiger forbruget med aktiviteten, men ved højere niveauer flader kurven ud, fordi kroppen delvist tilpasser sig.", "Praktisk betyder det, at du ikke kan 'træne dig ud af' en dårlig kost alene. Motion er vigtigt for hjerte, kredsløb, muskler og humør, men vægtkontrol handler både om kost og aktivitet.", "Brug derfor appen til at se begge sider: hvor meget du indtager, og hvor meget du bevæger dig."), null, OnbSourceLink("Pontzer H m.fl. (2016): Constrained total energy expenditure… Current Biology (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/26832439/"), emptyList()),
        KnowledgeArticle("styrketraening-og-forbraending", "kalorieforbraending", "Styrketræning og muskelmasse", "Muskler er aktive væv, og styrketræning er en del af de officielle anbefalinger.", listOf("Både WHO og Sundhedsstyrelsen anbefaler regelmæssig muskelstyrkende aktivitet ud over konditions- og hverdagsbevægelse. Muskler hjælper med at holde dig stærk, stabil og selvhjulpen langt op i årene.", "Muskelmasse er en del af, hvorfor to personer med samme vægt kan have forskelligt energibehov. Men effekten af ekstra muskler på hvileforbruget er moderat, så styrketræning er først og fremmest godt for helbredet — ikke en smutvej til at forbrænde meget mere.", "Tip: Kombinér styrketræning med gang eller anden konditionsaktivitet i løbet af ugen, og sørg for tilstrækkeligt protein og hvile."), null, OnbSourceLink("WHO: Physical activity (fact sheet)", "https://www.who.int/news-room/fact-sheets/detail/physical-activity"), listOf(OnbSourceLink("Borger.dk (Sundhedsstyrelsen): Motionsråd", "https://www.borger.dk/sundhed-og-sygdom/forebyg-sygdom/motionsraad"))),
        KnowledgeArticle("tips-og-tricks-til-forbraending", "kalorieforbraending", "Tips og tricks til en højere forbrænding", "Sådan samler du forskningen i enkle vaner.", listOf("Fordel dagen: Spis en solid morgenmad med protein, og hold aftensmaden moderat. Forskningen viser, at fordøjelsen kræver mere energi om morgenen.", "Bevæg dig hele dagen: Små pauser, trapper og gåture (NEAT) fylder i regnskabet, også når du ikke træner.", "Gå efter måltider: En kort tur efter maden er en nem vane, der bryder stillesiddende tid, som WHO anbefaler.", "Træn bredt: Sigt mod mindst 30 minutters moderat til høj aktivitet hver dag (Sundhedsstyrelsen) og muskelstyrkende aktivitet i ugen.", "Hold fast i helheden: Motion og kost hænger sammen, og kroppen tilpasser sig. Små, varige ændringer slår kortvarige kure.", "Er du i tvivl om kost eller træning på grund af sygdom, graviditet eller medicin, så tal med din læge."), null, OnbSourceLink("Borger.dk (Sundhedsstyrelsen): Motionsråd", "https://www.borger.dk/sundhed-og-sygdom/forebyg-sygdom/motionsraad"), listOf(OnbSourceLink("WHO: Guidelines on physical activity and sedentary behaviour (2020)", "https://www.who.int/publications/i/item/9789240015128"), OnbSourceLink("Richter J m.fl. (2020): Twice as high diet-induced thermogenesis after breakfast vs dinner. J Clin Endocrinol Metab (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/32073608/"), OnbSourceLink("Levine JA m.fl. (1999): Role of nonexercise activity thermogenesis in resistance to fat gain in humans. Science (PubMed)", "https://pubmed.ncbi.nlm.nih.gov/9880251/"))),
        KnowledgeArticle("who-fysisk-aktivitet", "who-og-kilder", "WHO: Fysisk aktivitet", "Mindst 150 minutters moderat aktivitet om ugen plus muskelstyrkende aktivitet.", listOf("WHO's retningslinjer fra 2020 anbefaler voksne mindst 150 minutters moderat fysisk aktivitet om ugen — eller tilsvarende mindre med høj intensitet — samt muskelstyrkende aktivitet.", "Retningslinjerne er de første fra WHO, der kobler stillesiddende adfærd til helbredet: Jo mere du sidder stille, jo vigtigere er det at bevæge dig.", "Sundhedsstyrelsen anbefaler voksne mindst 30 minutters daglig fysisk aktivitet med moderat til høj intensitet. Hvis aktiviteten opdeles, bør hver periode vare mindst 10 minutter."), null, OnbSourceLink("WHO: Physical activity (fact sheet)", "https://www.who.int/news-room/fact-sheets/detail/physical-activity"), listOf(OnbSourceLink("WHO: Guidelines on physical activity and sedentary behaviour (2020)", "https://www.who.int/publications/i/item/9789240015128"), OnbSourceLink("Borger.dk (Sundhedsstyrelsen): Motionsråd", "https://www.borger.dk/sundhed-og-sygdom/forebyg-sygdom/motionsraad"))),
        KnowledgeArticle("who-sund-kost", "who-og-kilder", "WHO: Sund kost", "Frugt og grønt, fibre, mindre sukker, salt og fedt.", listOf("WHO's faktaark om sund kost bygger på fire grundprincipper: tilstrækkelighed, balance, moderation og variation.", "Konkrete tal for voksne: mindst 400 g frugt og grønt om dagen, mindst 25 g kostfibre, højst 30 % af energien fra fedt, mindre end 10 % af energien fra sukker og under 5 g salt (2 g natrium) om dagen.", "WHO anbefaler at prioritere minimalt forarbejdede fødevarer og begrænse højt forarbejdede varer med meget salt, sukker og usunde fedtstoffer."), null, OnbSourceLink("WHO: Healthy diet (fact sheet)", "https://www.who.int/news-room/fact-sheets/detail/healthy-diet"), listOf(OnbSourceLink("Nordisk Ministerråd: Nordic Nutrition Recommendations 2023", "https://norden.org/en/publication/nordic-nutrition-recommendations-2023"))),
